# FDN High-Society Hunter: "Flying. Whenever this creature attacks, you may sacrifice another
# creature. If you do, put a +1/+1 counter on this creature. Whenever another nontoken creature
# dies, draw a card."
# [0]: "Whenever this creature attacks" (Library Larcenist's DeclareAttackersEvent over the source);
# effect: M21 Dire Fleet Warmonger's verified "you may sacrifice another creature. If you do, ..."
# with Lorescale Coatl's counter on this creature.
# [1]: a CreatureDiesEvent over any player's nontoken creature but this one (FNot(IS_TOKEN),
# FNot(IS_SOURCE)); "draw a card" (Crash Through).
attacks = TriggeredAbility(
    event=DeclareAttackersEvent(filter=FAtom(pred=FAtomPred.IS_SOURCE)),
    condition=None,
    effect=Seq(
        steps=(
            OptionalEffect(
                inner=A(Verb.SACRIFICE, {
                    'target': Selector(
                        count=QConst(value=1),
                        mode=SelectorMode.CHOOSE,
                        filter=FAnd(
                            children=(
                                FAtom(pred=FAtomPred.CONTROLLER_IS, who=ControllerRef.YOU),
                                FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                                FNot(inner=FAtom(pred=FAtomPred.IS_SOURCE)),
                            ),
                        ),
                        zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                    ),
                }),
            ),
            Conditional(
                pred=FAtom(pred=FAtomPred.MAY_DONE),
                then_effect=A(Verb.PUT_COUNTER, {
                    'count': QConst(value=1),
                    'counter_kind': CounterKind.PLUS_1_PLUS_1,
                    'target': Selector(
                        count=QConst(value=1),
                        mode=SelectorMode.CHOOSE,
                        filter=FAtom(pred=FAtomPred.IS_SOURCE),
                        zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                    ),
                }),
            ),
        ),
    ),
)
dies = TriggeredAbility(
    event=CreatureDiesEvent(
        filter=FAnd(
            children=(
                FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                FNot(inner=FAtom(pred=FAtomPred.IS_SOURCE)),
                FNot(inner=FAtom(pred=FAtomPred.IS_TOKEN)),
            ),
        ),
    ),
    condition=None,
    effect=A(Verb.DRAW, {'amount': QConst(value=1), 'controller': ControllerRef.YOU}),
)
abilities = [attacks, dies, *compiled]
